('770141f6-6441-4076-bbb0-fff28a63b37a', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "05a2f2d0-d620-405f-ab01-139a56e21e05", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "18e69008-9131-496d-b9db-862e4fd07461", "text": "3/5", "isCorrect": true}, {"id": "b29be2a1-6448-42fb-8a6a-d65200a8e2c9", "text": "3/10", "isCorrect": false}, {"id": "e4477463-0612-4e1a-b1c9-3a68bb634e17", "text": "2/10", "isCorrect": false}, {"id": "1ffce2a3-6a1c-42bc-82a3-7cbce1bc2187", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "e60f40e0-24d8-4eb9-9238-43665bc93b95", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "ee39e846-eff4-4937-b3f6-cb4b2e9eeb37", "text": "1/4", "isCorrect": true}, {"id": "5971a1e8-13be-412f-a454-9adb6b023e1f", "text": "2/2", "isCorrect": false}, {"id": "1f7e26b1-7a6d-4ee4-8b92-b189989a016a", "text": "1/2", "isCorrect": false}, {"id": "3249117e-e676-4411-b2f9-9b464caa3e5a", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "3c4ae0f8-cf9e-412b-ae3c-01a0f811ed7c", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "a3c64744-a049-42b9-9332-ef19c18bd1d7", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "7976e57e-071d-4771-a41d-4cce0c2659ca", "text": "5/7", "isCorrect": false}, {"id": "e3b5f81e-4c7d-4203-9d38-ad614a0cc4fe", "text": "6/7", "isCorrect": false}, {"id": "2e3fb070-82ad-4c30-bc8d-95f1a17f30d7", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "b1c97399-13af-4997-87fe-b4ee03eee422", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "631d1fb8-0386-432f-a3d9-4c8def174833", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "155dbd1c-1904-4d0c-bec9-de69bc1f8da0", "text": "8/7", "isCorrect": true}, {"id":