: "4ec45982-5bfc-4f90-a711-33ea39fbf1d2", "text": "2/5", "isCorrect": false}, {"id": "22ca8bc4-bbf2-4171-b05c-92c9f6c55abf", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "ca93f259-e20f-408c-aa94-2a46e996bf97", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "d718c5d9-1904-4ba2-acda-57794e00dc60", "text": "Igaz", "isCorrect": true}, {"id": "ee92956d-df60-45a0-8d8b-cf3a55d53d90", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ba1d60e7-0c0c-46d4-9999-8f7806e24d12", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "8e050479-aa88-4f8d-b176-ea85f3e23914", "text": "1/5", "isCorrect": true}, {"id": "a0d71888-1bc8-48d0-be22-c957af313b39", "text": "2/10", "isCorrect": false}, {"id": "fe950906-0fb5-4674-9297-1da62dea94e0", "text": "1/2", "isCorrect": false}, {"id": "773229bf-4e73-4233-937d-e41787eed0cf", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "37df91d0-0f9a-4d07-be4e-f4af6d70f7dc", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "64cb1e10-e22b-4241-9080-ca07eb373e99", "text": "Igaz", "isCorrect": true}, {"id": "a2b39770-8754-4fd1-a400-44c58d63050e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
