4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "44642851-801f-4e38-ad85-194c693bc46a", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "ed58b389-6b81-4f83-8676-3619ac1129e2", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "5002273c-e804-4355-baa1-9b82c85ce265", "text": "4,05", "isCorrect": false}, {"id": "65194b1c-a970-432e-9834-314041d6d85c", "text": "Egyenlőek", "isCorrect": false}, {"id": "9e031270-cf0e-48df-9a46-4e8216bbea79", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
